"""Validate actual JFR event types, then extract and summarize selected events."""
import json
import os
from pathlib import Path
import re
import subprocess
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
JFR = Path(os.environ["JAVA_HOME"]) / "bin/jfr"
ALLOWED = {"jdk.ExecutionSample", "jdk.NativeMethodSample", "jdk.ObjectAllocationSample",
           "jdk.GarbageCollection", "jdk.CPULoad", "jdk.ThreadCPULoad", "jdk.Checkpoint", "jdk.Metadata"}
files = [Path(name) for name in sys.argv[1:]] or sorted((ROOT / "profiles").glob("*.jfr"))
if not files:
    raise SystemExit("No recordings to inspect")
for recording in files:
    summary = subprocess.check_output([str(JFR), "summary", str(recording)], text=True)
    inventory = {}
    for line in summary.splitlines():
        match = re.fullmatch(r"\s*(\S+)\s+(\d+)\s+(\d+)\s*", line)
        if match and int(match[2]):
            inventory[match[1]] = int(match[2])
    if not inventory:
        raise RuntimeError("No recognized JFR inventory: " + str(recording))
    unexpected = set(inventory) - ALLOWED
    if unexpected:
        raise RuntimeError("Unexpected recorded event types: " + repr(unexpected))
    recording.with_suffix(".inventory.txt").write_text(summary)
    recording.with_suffix(".inventory.json").write_text(json.dumps(inventory, indent=2) + "\n")
    events = recording.with_suffix(".events.json")
    with events.open("w") as output:
        subprocess.run([str(JFR), "print", "--json", "--stack-depth", "128", "--events",
                        "jdk.ExecutionSample,jdk.ObjectAllocationSample", str(recording)], stdout=output, check=True)
    subprocess.run([sys.executable, str(HERE / "summarize_jfr.py"), str(events),
                    "--json", str(recording.with_suffix(".summary.json")),
                    "--markdown", str(recording.with_suffix(".summary.md"))], check=True)
    print(recording.name, "event inventory verified:", inventory, flush=True)
